'use server'

import { refresh } from 'next/cache'
import {
  getNotificationPreference,
  setNotificationPreference,
} from '@/app/lib/preferences'

export async function toggleNotifications() {
  // In a real app, authenticate/authorize the user here before mutating.
  const current = await getNotificationPreference()
  await setNotificationPreference(!current)

  // Refresh the client router so the current page re-renders with the
  // updated preference — no redirect to a different route.
  refresh()
}

